function grammarFramework(){return `<section class="atlas" aria-label="英语语法导图">
 <div class="atlas-toolbar"><div><strong>语法全景</strong><small id="atlas-count"></small></div><div class="atlas-tools"><select id="atlas-branch" aria-label="选择语法分支"><option value="">全部领域</option></select><button data-atlas="expand">全部展开</button><button data-atlas="overview">主干</button><button data-atlas="fullscreen" aria-label="全屏查看">全屏 ⛶</button></div></div>
 <div class="atlas-search"><span>⌕</span><input id="atlas-search" type="search" placeholder="搜索知识点，例如：双宾语、过去完成、虚拟…" aria-label="搜索导图知识点" aria-controls="atlas-search-results"><div id="atlas-search-results" hidden></div></div>
 <div class="atlas-viewport" tabindex="0" aria-label="可拖动缩放的语法导图" aria-describedby="atlas-help"><div class="atlas-stage"></div><div class="atlas-zoom"><button data-atlas="out" aria-label="缩小">−</button><output id="atlas-scale" aria-label="当前缩放比例">100%</output><button data-atlas="in" aria-label="放大">＋</button><button data-atlas="fit">全图</button><button data-atlas="actual">100%</button></div><svg class="atlas-minimap" aria-label="导图缩略图" role="img"></svg><aside class="atlas-info" hidden aria-label="知识点说明"></aside></div>
 <div class="atlas-bottom"><span id="atlas-help">拖动平移 · 滚轮缩放 · 触屏可双指缩放 · 点击 + 展开</span><span id="atlas-visible" role="status"></span></div>
 </section>`}

function mountAtlas(root){
 const viewport=root.querySelector('.atlas-viewport'),stage=root.querySelector('.atlas-stage'),info=root.querySelector('.atlas-info'),mini=root.querySelector('.atlas-minimap');
 const branch=root.querySelector('#atlas-branch'),search=root.querySelector('#atlas-search'),results=root.querySelector('#atlas-search-results');
 const palette=['#899f70','#b2a271','#7fa2aa','#8a9cbb','#bf9d7e','#a099b7','#839a82','#b1a06f'];
 const nodes=[],byId=new Map(),collapsed=new Set();
 function prepare(data,parent=null,depth=0,index=0){const node={...data,parent,depth,id:parent?`${parent.id}-${index}`:'root',color:depth===1?palette[index]:parent?.color||'#3c6040',lesson:data.lesson||parent?.lesson};nodes.push(node);byId.set(node.id,node);node.children=(data.children||[]).map((child,i)=>prepare(child,node,depth+1,i));if(depth===2&&node.children.length)collapsed.add(node.id);return node;}
 const tree=prepare(grammarAtlas);
 root.querySelector('#atlas-count').textContent=`${tree.children.length} 个领域 · ${nodes.length-1} 个知识点`;
 branch.innerHTML+='<option disabled>────────</option>'+tree.children.map(n=>`<option value="${n.id}">${esc(n.title)}</option>`).join('');
 let scope='',selected=null,visible=[],edges=[],width=2050,height=1000,scale=1,tx=0,ty=0,disposed=false,frame;
 const H=40,GAP=10;
 const children=n=>collapsed.has(n.id)?[]:n.children;
 function measure(n){const list=children(n);n.size=list.length?Math.max(H,list.reduce((sum,c)=>sum+measure(c),0)+(list.length-1)*GAP):H;return n.size;}
 function arrange(n,cx,top,side,level){n.x=cx;n.y=top+n.size/2;n.w=level===0?180:level===1?170:level===2?184:224;n.side=side;visible.push(n);const list=children(n);let cursor=top;for(const child of list){arrange(child,cx+side*(level>=2?264:254),cursor,side,level+1);edges.push([n,child]);cursor+=child.size+GAP;}}
 function path(a,b){const side=b.x>=a.x?1:-1;const x1=a.x+side*a.w/2,x2=b.x-side*b.w/2;const bend=(x1+x2)/2;return `M${x1},${a.y} C${bend},${a.y} ${bend},${b.y} ${x2},${b.y}`;}
 function layout(){visible=[];edges=[];
  if(scope){const head=byId.get(scope);measure(head);height=head.size+100;arrange(head,180,50,1,0);width=1120;}
  else {const sides=[[],[]],sizes=[0,0];for(const group of children(tree)){measure(group);const i=sizes[0]<=sizes[1]?0:1;sides[i].push(group);sizes[i]+=group.size+32;}height=Math.max(...sizes)+100;tree.x=1025;tree.y=height/2;tree.w=180;visible.push(tree);for(let i=0;i<2;i++){const side=i?1:-1;let cursor=(height-sizes[i]+32)/2;for(const group of sides[i]){arrange(group,tree.x+side*270,cursor,side,1);edges.push([tree,group]);cursor+=group.size+32;}}width=2050;}
  const minX=Math.min(...visible.map(n=>n.x-n.w/2)),maxX=Math.max(...visible.map(n=>n.x+n.w/2)),minY=Math.min(...visible.map(n=>n.y-H/2)),maxY=Math.max(...visible.map(n=>n.y+H/2));for(const n of visible){n.x+=60-minX;n.y+=60-minY;}width=maxX-minX+120;height=maxY-minY+120;
 }
 function draw(){layout();stage.style.width=`${width}px`;stage.style.height=`${height}px`;stage.innerHTML=`<svg class="atlas-connections" width="${width}" height="${height}" aria-hidden="true">${edges.map(([a,b])=>`<path d="${path(a,b)}" stroke="${b.color}"/>`).join('')}</svg>${visible.map(n=>`<div class="atlas-node atlas-depth-${n.depth}${selected===n.id?' selected':''}" style="left:${n.x-n.w/2}px;top:${n.y-H/2}px;width:${n.w}px;--node-color:${n.color}" data-node="${n.id}"><button class="atlas-label" data-node-id="${n.id}" aria-pressed="${selected===n.id}" title="${esc(n.title)}">${esc(n.title)}</button>${n.children.length?`<button class="atlas-toggle" data-toggle-id="${n.id}" aria-label="${collapsed.has(n.id)?'展开':'折叠'}${esc(n.title)}" aria-expanded="${!collapsed.has(n.id)}">${collapsed.has(n.id)?'+':'−'}</button>`:''}</div>`).join('')}`;
  stage.querySelectorAll('button').forEach(button=>button.onclick=e=>{if(e.detail===0)activate(button);});
  root.querySelector('#atlas-visible').textContent=`当前 ${visible.length} / ${nodes.length} 节点`;
  mini.setAttribute('viewBox',`0 0 ${width} ${height}`);mini.innerHTML=`${edges.map(([a,b])=>`<path d="${path(a,b)}" stroke="${b.color}" fill="none" stroke-width="5"/>`).join('')}${visible.filter(n=>n.depth<3).map(n=>`<rect x="${n.x-n.w/2}" y="${n.y-H/2}" width="${n.w}" height="${H}" rx="8" fill="${n.color}"/>`).join('')}<rect class="minimap-view" fill="#829f6830" stroke="#36583b" stroke-width="8"/>`;
  transform();
 }
 function transform(){if(disposed)return;stage.style.transform=`translate(${tx}px,${ty}px) scale(${scale})`;root.querySelector('#atlas-scale').textContent=`${Math.round(scale*100)}%`;const r=mini.querySelector('.minimap-view');if(r){r.setAttribute('x',-tx/scale);r.setAttribute('y',-ty/scale);r.setAttribute('width',viewport.clientWidth/scale);r.setAttribute('height',viewport.clientHeight/scale);}}
 function setScale(value,x=viewport.clientWidth/2,y=viewport.clientHeight/2){const next=Math.max(.04,Math.min(3,value));const worldX=(x-tx)/scale,worldY=(y-ty)/scale;scale=next;tx=x-worldX*scale;ty=y-worldY*scale;transform();}
 function fit(){const padding=35;scale=Math.max(.04,Math.min(1,(viewport.clientWidth-padding*2)/width,(viewport.clientHeight-padding*2)/height));tx=(viewport.clientWidth-width*scale)/2;ty=(viewport.clientHeight-height*scale)/2;transform();}
 function center(n,zoom=1){scale=Math.max(.04,Math.min(3,zoom));tx=viewport.clientWidth/2-n.x*scale;ty=viewport.clientHeight/2-n.y*scale;transform();}
 function ancestors(n){const list=[];for(let at=n;at;at=at.parent)list.unshift(at);return list;}
 function showInfo(n){selected=n.id;stage.querySelectorAll('.atlas-node').forEach(el=>{const active=el.dataset.node===n.id;el.classList.toggle('selected',active);el.querySelector('.atlas-label').setAttribute('aria-pressed',String(active));});const lesson=lessons.find(l=>l.id===n.lesson);info.hidden=false;info.innerHTML=`<button class="atlas-info-close" aria-label="关闭知识点说明">×</button><small>${ancestors(n).slice(0,-1).map(x=>esc(x.title)).join(' / ')}</small><h3>${esc(n.title)}</h3><p>${esc(n.detail||'点击下方分支查看具体知识点。')}</p>${n.example?`<div class="atlas-info-example">${esc(n.example)}</div>`:''}<div class="atlas-info-actions">${n.children.length?`<button class="atlas-info-expand">${collapsed.has(n.id)?'展开分支':'收起分支'}</button>`:''}${lesson?`<a href="#lesson/${lesson.id}">相关课程：${esc(lesson.title)} →</a>`:''}</div>`;info.querySelector('.atlas-info-close').onclick=()=>{info.hidden=true;selected=null;stage.querySelector('.selected .atlas-label')?.setAttribute('aria-pressed','false');stage.querySelector('.selected')?.classList.remove('selected');};const expand=info.querySelector('.atlas-info-expand');if(expand)expand.onclick=()=>toggle(n);}
 function toggle(n){if(!n.children.length)return;collapsed.has(n.id)?collapsed.delete(n.id):collapsed.add(n.id);draw();center(n,scale);showInfo(n);stage.querySelector(`[data-toggle-id="${n.id}"]`)?.focus({preventScroll:true});}
 function activate(button){const toggleId=button.dataset.toggleId,nodeId=button.dataset.nodeId;if(toggleId)toggle(byId.get(toggleId));else if(nodeId)showInfo(byId.get(nodeId));}
 function reveal(n){scope='';branch.value='';for(const a of ancestors(n))collapsed.delete(a.id);draw();center(n,1);showInfo(n);results.hidden=true;}
 search.oninput=()=>{const q=search.value.trim().toLowerCase();results.hidden=!q;if(!q)return;const matches=nodes.filter(n=>`${n.title} ${n.example||''} ${n.detail||''}`.toLowerCase().includes(q));results.innerHTML=`<small>${matches.length} 个结果${matches.length>30?'，显示前 30 个':''}</small>${matches.slice(0,30).map(n=>`<button data-result="${n.id}"><strong>${esc(n.title)}</strong><small>${ancestors(n).slice(1,-1).map(x=>esc(x.title)).join(' / ')}</small></button>`).join('')||'<p>没有匹配的知识点</p>'}`;results.querySelectorAll('[data-result]').forEach(b=>b.onclick=()=>reveal(byId.get(b.dataset.result)));};
 search.onkeydown=e=>{if(e.key==='Escape')results.hidden=true;if(e.key==='Enter'){const first=results.querySelector('[data-result]');if(first){e.preventDefault();first.click();}}};
 branch.onchange=()=>{scope=branch.value;if(scope){const group=byId.get(scope);collapsed.delete(group.id);group.children.forEach(n=>collapsed.delete(n.id));}info.hidden=true;draw();fit();};
 const actions={in:()=>setScale(scale*1.25),out:()=>setScale(scale/1.25),fit,actual:()=>setScale(1),expand:()=>{collapsed.clear();draw();fit();},overview:()=>{collapsed.clear();nodes.filter(n=>n.depth===2).forEach(n=>collapsed.add(n.id));scope='';branch.value='';info.hidden=true;draw();fit();},fullscreen:async()=>{try{if(document.fullscreenElement===root)await document.exitFullscreen();else if(root.classList.contains('atlas-expanded'))root.classList.remove('atlas-expanded');else await root.requestFullscreen();}catch{root.classList.toggle('atlas-expanded');}requestAnimationFrame(fit);}};
 root.querySelectorAll('[data-atlas]').forEach(b=>b.onclick=()=>actions[b.dataset.atlas]());
 const points=new Map();let start=null,pinch=null,moved=false,pressed=null;
 viewport.addEventListener('pointerdown',e=>{if(e.button!==0||e.target.closest('.atlas-zoom,.atlas-info,.atlas-minimap'))return;e.preventDefault();results.hidden=true;points.set(e.pointerId,{x:e.clientX,y:e.clientY});viewport.setPointerCapture(e.pointerId);if(points.size===1){start={x:e.clientX,y:e.clientY,tx,ty};moved=false;pressed=e.target.closest('.atlas-label,.atlas-toggle');}if(points.size===2){const p=[...points.values()];const rect=viewport.getBoundingClientRect(),x=(p[0].x+p[1].x)/2-rect.left,y=(p[0].y+p[1].y)/2-rect.top;pinch={distance:Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y),scale,worldX:(x-tx)/scale,worldY:(y-ty)/scale};moved=true;pressed=null;}viewport.classList.add('panning');});
 viewport.addEventListener('pointermove',e=>{if(!points.has(e.pointerId))return;points.set(e.pointerId,{x:e.clientX,y:e.clientY});if(points.size===2&&pinch){const p=[...points.values()],rect=viewport.getBoundingClientRect(),x=(p[0].x+p[1].x)/2-rect.left,y=(p[0].y+p[1].y)/2-rect.top;scale=Math.max(.04,Math.min(3,pinch.scale*Math.hypot(p[0].x-p[1].x,p[0].y-p[1].y)/Math.max(1,pinch.distance)));tx=x-pinch.worldX*scale;ty=y-pinch.worldY*scale;transform();}else if(points.size===1&&start){const dx=e.clientX-start.x,dy=e.clientY-start.y;if(Math.hypot(dx,dy)>5)moved=true;tx=start.tx+dx;ty=start.ty+dy;transform();}});
 function endPointer(e){if(!points.has(e.pointerId))return;if(e.type==='pointerup'&&!moved&&pressed)activate(pressed);points.delete(e.pointerId);if(points.size===1){const p=[...points.values()][0];start={x:p.x,y:p.y,tx,ty};pinch=null;pressed=null;moved=true;}if(!points.size){start=null;pinch=null;pressed=null;viewport.classList.remove('panning');}}
 viewport.addEventListener('pointerup',endPointer);viewport.addEventListener('pointercancel',endPointer);viewport.addEventListener('lostpointercapture',endPointer);
 viewport.addEventListener('wheel',e=>{if(e.target.closest('.atlas-info'))return;e.preventDefault();const r=viewport.getBoundingClientRect();setScale(scale*Math.exp(-Math.max(-160,Math.min(160,e.deltaY))*.002),e.clientX-r.left,e.clientY-r.top);},{passive:false});
 viewport.addEventListener('keydown',e=>{if(e.target!==viewport)return;const shifts={ArrowLeft:[50,0],ArrowRight:[-50,0],ArrowUp:[0,50],ArrowDown:[0,-50]};if(shifts[e.key]){e.preventDefault();tx+=shifts[e.key][0];ty+=shifts[e.key][1];transform();}else if(e.key==='+'||e.key==='='){e.preventDefault();actions.in();}else if(e.key==='-'){e.preventDefault();actions.out();}else if(e.key==='0'){e.preventDefault();fit();}});
 mini.onclick=e=>{const matrix=mini.getScreenCTM();if(!matrix)return;const point=new DOMPoint(e.clientX,e.clientY).matrixTransform(matrix.inverse());center({x:point.x,y:point.y},scale);};
 const observer=new ResizeObserver(()=>{cancelAnimationFrame(frame);frame=requestAnimationFrame(()=>{if(!disposed)fit();});});observer.observe(viewport);
 draw();fit();
 return {destroy(){disposed=true;observer.disconnect();cancelAnimationFrame(frame);if(document.fullscreenElement===root)document.exitFullscreen().catch(()=>{});}};
}
